def flatten(nested: list) -> list:
    """Flatten arbitrarily nested lists into one list, preserving order."""
    result = []
    def flatten_helper(lst):
        for item in lst:
            if isinstance(item, list):
                flatten_helper(item)
            else:
                result.append(item)
    flatten_helper(nested)
    return result
