def roman_to_int(s: str) -> int:
    roman = {'I': 1, 'V': 5, 'X': 10, 'L': 50, 'C': 100, 'D': 500, 'M': 1000}
    total = 0
    for i in range(len(s) - 1, 0, -1):
        current = roman[s[i]]
        next_char = roman[s[i+1]] if i+1 < len(s) else 0
        if current < next_char:
            total -= current
        else:
            total += current
    return total
```

