def lru_misses(capacity: int, accesses: list[int]) -> int:
    from collections import deque

    cache = deque()
    misses = 0

    for access in accesses:
        if len(cache) < capacity:
            cache.append(access)
            misses += 1
        else:
            if access in cache:
                # LRU cache: remove the oldest element
                cache.appendleft(access)
                cache.pop()
            else:
                misses += 1
                cache.append(access)

    return misses
```

