def parse_duration(s: str) -> int:
    """Seconds in a duration like '1h30m15s' (each of h, m, s optional, in that order); raise ValueError if invalid or empty."""
    if not s:
        raise ValueError("Empty string")

    total_seconds = 0
    i = 0

    while i < len(s):
        char = s[i]
        if char in 'hms':
            # Check if the next character is a digit
            if i + 1 < len(s) and s[i + 1].isdigit():
                # Parse hours
                if char == 'h':
                    hours = int(s[i])
                    total_seconds += hours * 3600
                    i += 2
                elif char == 'm':
                    minutes = int(s[i])
                    total_seconds += minutes * 60
                    i += 2
                elif char == 's':
                    seconds = int(s[i])
                    total_seconds += seconds
                    i += 2
                else:
                    raise ValueError("Invalid character")
            else:
                raise ValueError("Invalid digit after unit")
        else:
            i += 1

    return total_seconds
